  let S, N = 43, SPT = 3; // overall size, num cols/rows, stripes per cell

function setup() {
	S = max(windowWidth, windowHeight);
	S = ~~(S / N / SPT) * SPT;
	createCanvas(S * N, S * N);
	describe("overlaying lines slightly rotated and colored");

	describe("mask");
	background(32);
	noStroke();
	fill("gold");
	rect(0, 0, width, height);
	loop();
}

function draw() {
	// noLoop() removed for animation	

	const sw = S/SPT;
	fill("blue"); makeLines();
	stroke("purple"); makeLines();

	makeBlock(color("purple"), color("yellow"));
	if (false) {		
		translate(width/2, height/2)
		rotate(-0.2);
		translate(-width/2, -height/4)
	}
	makeBlock(color("deeppink"), color("cyan"));
	if (false) {		
		translate(width/2, height/4)
		rotate(0.2);
		translate(-width/2, -height/2)
	}
	makeBlock(color("navy"), color("white"));

	// maskFirst("#3333CC");
}

function mousePressed() {
	if (mouseButton !== RIGHT && (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) > width*0.1) setup();
}

function makeBlock(clr1, clr2) {
	push();
	fill(255);
	beginClip({ invert: false });
	makeLines();
	endClip();
	for (let i = 1; i < N/2; i++) {
		fill(lerpColor(clr1, clr2, 2*i/N));
		if (i == 1) drawOuterRect(0, 0, N, N);
		drawOuterRect(i, i-1, N-2*i, N-2*(i-1));
	}
	pop();
}

function makeLines() {
	const sw = S/SPT;
	push()
	rectMode(CENTER);
	translate(width/2, height/2);
	rotate(random(-0.15, 0.05));
	// translate(-width/2, -height/2);
	translate(random(-S/SPT, S/SPT), random(-S/SPT, S/SPT));
	const dx = S+S;
	for (let x = -width/2 - dx; x < width/2 + dx; x += sw+sw) {
		push();
		const y = (noise(x/S, frameCount/123)-0.5) * S;
		const a = (noise(frameCount/123, x/S, y/S)-0.5) * PI * 0.04;
		translate(x, y);
		rotate(a);
		rect(0, 0, sw, height+dx+dx); // line(x, -dx, x, height+dx);
		pop();
	}
	pop();
}

function drawRect(x, y, w, h) {
	rect(x*S, y*S, w*S, h*S);
}
function drawOuterRect(x, y, w, h) {
	drawHLine(x-w, y, w+w); 
	drawHLine(x-w, y+h-1, w+w); 
	drawVLine(x, y-h, h+h); 
	drawVLine(x+w-1, y-h, h+h); 
	return;
	drawHLine(x, y, w); // maskLine(x, y, w, y);
	drawHLine(x, y+h-1, w); // maskLine(x, y+h-1, w, y+h-1);
	drawVLine(x, y, h); // maskLine(x, y, x, h);
	drawVLine(x+w-1, y, h); // maskLine(x+w-1, y, x+w-1, h);
}
function drawHLine(x, y, n=1) {
	rect(x*S, y*S, n*S, S);
}
function drawVLine(x, y, n=1) {
	rect(x*S, y*S, S, n*S);
}

function maskFirst(clr) {
	const dx = S / SPT;
	push();
	beginClip({ invert: true });
	for (let x = 0; x < width; x += dx+dx) {
		rect(x, 0, dx, height)
	}
	endClip();
	fill(clr);
	rect(0, 0, width, height);
	pop();
}

function drawRect(x, y, w, h) {
	rect(x*S, y*S, w*S, h*S);
}
function drawOuterRect(x, y, w, h) {
	drawHLine(x, y, w); // maskLine(x, y, w, y);
	drawHLine(x, y+h-1, w); // maskLine(x, y+h-1, w, y+h-1);
	drawVLine(x, y, h); // maskLine(x, y, x, h);
	drawVLine(x+w-1, y, h); // maskLine(x+w-1, y, x+w-1, h);
}
function drawHLine(x, y, n=1) {
	rect(x*S, y*S, n*S, S);
}
function drawVLine(x, y, n=1) {
	rect(x*S, y*S, S, n*S);
}

function drawShape(x, y, S) {
	push();
	const dx = random() < 0.5 ? 0 : S; 
	const dy = random() < 0.5 ? 0 : S; 
	beginClip({ invert: true });
	circle(x + dx, y + dy, S)
	endClip();
	fill(random(pal));
	circle(x + S / 2, y + S / 2, S);
	pop();
}
